<?php
require __DIR__.'/config.php'; require_login('teacher');
$pdo=db(); $uid=current_user()['id']; $page=$_GET['page']??'dashboard';
$q=$pdo->prepare('SELECT * FROM teacher WHERE ID=?');$q->execute([$uid]);$teacher=$q->fetch();
if(!$teacher){session_destroy();header('Location:index.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 try {
  if($action==='save_content'){
   $id=(int)$_POST['id'];$fields=[trim($_POST['activity']??''),trim($_POST['c1']??''),trim($_POST['c2']??''),trim($_POST['c3']??''),trim($_POST['c4']??''),trim($_POST['answer']??'')];
   $s=$pdo->prepare('UPDATE teacher_content SET Exam=?,Choice1=?,Choice2=?,Choice3=?,Choice4=?,Answer=? WHERE Indicate=?');$s->execute([...$fields,$id]);flash('Content row #'.$id.' saved to the database.');
  } elseif($action==='reset_content'){
   // Always read the current default from admin_content; never use browser-side values.
   $id=(int)($_POST['id']??0);
   if($id<1) throw new RuntimeException('Invalid content row selected.');
   $source=$pdo->prepare('SELECT Exam,Choice1,Choice2,Choice3,Choice4,Answer FROM admin_content WHERE Indicate=?');
   $source->execute([$id]);
   $defaults=$source->fetch();
   if(!$defaults) throw new RuntimeException('The matching row was not found in admin_content. No changes were made.');
   $target=$pdo->prepare('SELECT 1 FROM teacher_content WHERE Indicate=?');
   $target->execute([$id]);
   if($target->fetchColumn()) {
    $pdo->prepare('UPDATE teacher_content SET Exam=?,Choice1=?,Choice2=?,Choice3=?,Choice4=?,Answer=? WHERE Indicate=?')
        ->execute([$defaults['Exam'],$defaults['Choice1'],$defaults['Choice2'],$defaults['Choice3'],$defaults['Choice4'],$defaults['Answer'],$id]);
   } else {
    $pdo->prepare('INSERT INTO teacher_content (Indicate,Exam,Choice1,Choice2,Choice3,Choice4,Answer) VALUES (?,?,?,?,?,?,?)')
        ->execute([$id,$defaults['Exam'],$defaults['Choice1'],$defaults['Choice2'],$defaults['Choice3'],$defaults['Choice4'],$defaults['Answer']]);
   }
   flash('Content row #'.$id.' was restored from the current admin_content database default.');
  }
  elseif($action==='profile'){
   $name=[trim($_POST['first']??''),trim($_POST['middle']??''),trim($_POST['last']??''),trim($_POST['subject']??'')];
   $pdo->prepare('UPDATE teacher SET First_Name=?,Middle_Initials=?,Last_Name=?,Subject=? WHERE ID=?')->execute([...$name,$uid]);
   $_SESSION['user']['name']=trim(implode(' ',array_filter(array_slice($name,0,3))));flash('Profile details updated.');header('Location: teacher.php?page=profile');exit;
  } elseif($action==='password'){
   $old=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';
   if(!verify_legacy_password($old,$teacher['Password'])) flash('Current password is incorrect.','error');
   elseif(strlen($new)<8) flash('Use a new password with at least 8 characters.','error');
   elseif($new!==$confirm) flash('The new passwords do not match.','error');
   else {$pdo->prepare('UPDATE teacher SET Password=? WHERE ID=?')->execute([password_hash($new,PASSWORD_DEFAULT),$uid]);flash('Password changed successfully.');}
   header('Location: teacher.php?page=profile');exit;
  } elseif($action==='picture' && isset($_FILES['picture']) && $_FILES['picture']['error']===UPLOAD_ERR_OK){
   if($_FILES['picture']['size']>3*1024*1024) throw new RuntimeException('Picture must be 3 MB or smaller.');
   $info=getimagesize($_FILES['picture']['tmp_name']); if(!$info) throw new RuntimeException('Please upload a valid image.');
   $ext=match($info['mime']){'image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif',default=>''};
   if(!$ext) throw new RuntimeException('Use JPG, PNG, WEBP or GIF.');
   if(!is_dir(__DIR__.'/uploads'))mkdir(__DIR__.'/uploads',0755,true);
   $file='teacher_'.$uid.'_'.bin2hex(random_bytes(5)).'.'.$ext;
   if(!move_uploaded_file($_FILES['picture']['tmp_name'],__DIR__.'/uploads/'.$file))throw new RuntimeException('Could not save picture. Check folder permissions.');
   if(!empty($teacher['Profile_Picture']) && is_file(__DIR__.'/'.$teacher['Profile_Picture']))@unlink(__DIR__.'/'.$teacher['Profile_Picture']);
   $pdo->prepare('UPDATE teacher SET Profile_Picture=? WHERE ID=?')->execute(['uploads/'.$file,$uid]);flash('Profile picture updated.');
   header('Location: teacher.php?page=profile');exit;
  }
 }catch(Throwable $e){flash($e instanceof RuntimeException?$e->getMessage():'Could not save changes. Please check the database setup.','error');}
 header('Location: teacher.php?page='.$page);exit;
}
$section=$_GET['section']??'all';
$sections=$pdo->query('SELECT Name FROM section ORDER BY Name')->fetchAll(PDO::FETCH_COLUMN);
$sql='SELECT * FROM student';$args=[];if($section!=='all' && in_array($section,$sections,true)){$sql.=' WHERE Section=?';$args[]=$section;}$sql.=' ORDER BY Section,Last_Name,First_Name';
$st=$pdo->prepare($sql);$st->execute($args);$students=$st->fetchAll();
$content=$pdo->query('SELECT * FROM teacher_content ORDER BY Indicate')->fetchAll();
$studentProfile=null;$tests=[];
if($page==='student' && isset($_GET['id'])){$q=$pdo->prepare('SELECT * FROM student WHERE ID=?');$q->execute([$_GET['id']]);$studentProfile=$q->fetch();if($studentProfile){try{$q=$pdo->prepare('SELECT Chapter,Pre_test_Scores,Post_test_Scores FROM records WHERE student_id=? ORDER BY Chapter');$q->execute([$studentProfile['ID']]);$tests=$q->fetchAll();}catch(Throwable $e){$tests=[];}}}
$ranking=[];foreach($sections as $sec){$rows=array_values(array_filter($students,fn($s)=>$s['Section']===$sec));$ranking[]=['name'=>$sec,'progress'=>$rows?round(array_sum(array_column($rows,'Progress'))/count($rows),1):0,'mastery'=>$rows?round(array_sum(array_map(fn($s)=>(float)($s['Mastery']??0),$rows))/count($rows),2):0,'count'=>count($rows)];}
function nav_active($p,$current){return $p===$current?'active':'';}
?>
