<div class="stats-grid"><article class="stat-card"><span class="stat-icon">♙</span><small>Total students</small><strong><?=count($students)?></strong><span class="stat-foot">Across listed sections</span></article><article class="stat-card"><span class="stat-icon">↗</span><small>Average progress</small><strong><?=count($students)?round(array_sum(array_column($students,'Progress'))/count($students),1):0?>%</strong><span class="stat-foot">Based on student records</span></article><article class="stat-card"><span class="stat-icon">✦</span><small>Average mastery</small><strong><?=count($students)?round(array_sum(array_map(fn($s)=>(float)($s['Mastery']??0),$students))/count($students),2):0?></strong><span class="stat-foot">Mastery value from database</span></article><article class="stat-card"><span class="stat-icon">▤</span><small>Learning activities</small><strong><?=count($content)?></strong><span class="stat-foot">Items in teacher content</span></article></div>
<section class="panel chart-panel"><div class="panel-heading"><div><h3>Section performance ranking</h3><p>Compare average progress and mastery by section.</p></div><label class="compact-select">Section <select id="chartSection"><option value="all">All sections</option><?php foreach($sections as $sec):?><option value="<?=e($sec)?>"><?=e($sec)?></option><?php endforeach;?></select></label></div><div class="chart-wrap"><canvas id="sectionChart" height="115"></canvas></div><div class="chart-legend"><span><i class="legend-red"></i> Average progress (%)</span><span><i class="legend-gold"></i> Average mastery (× 20 for visual scale)</span></div></section>
<section class="panel"><div class="panel-heading"><div><h3>Student directory</h3><p>Select a student row to open their profile and assessment history.</p></div><label class="compact-select">Filter section <select id="studentFilter"><option value="all">All sections</option><?php foreach($sections as $sec):?><option value="<?=e($sec)?>" <?=$section===$sec?'selected':''?>><?=e($sec)?></option><?php endforeach;?></select></label></div><div class="table-scroll"><table><thead><tr><th>First name</th><th>Middle name</th><th>Last name</th><th>Student ID</th><th>Section</th><th>Progress</th><th>Mastery</th></tr></thead><tbody><?php foreach($students as $s):?><tr class="click-row" tabindex="0" data-href="teacher.php?page=student&id=<?=e($s['ID'])?>"><td><strong><?=e($s['First_Name']?:$s['PlayerName'])?></strong></td><td><?=e($s['Middle_Initials'])?></td><td><?=e($s['Last_Name'])?></td><td><?=e($s['ID'])?></td><td><span class="section-pill"><?=e($s['Section'])?></span></td><td><div class="progress-cell"><div class="progress-track"><span style="width:<?=max(0,min(100,(float)$s['Progress']))?>%"></span></div><b><?=e($s['Progress'])?>%</b></div></td><td><span class="mastery-badge"><?=e($s['Mastery']??'—')?></span></td></tr><?php endforeach;?><?php if(!$students):?><tr><td colspan="7" class="empty">No students found in this section.</td></tr><?php endif;?></tbody></table></div></section>
<?php elseif($page==='student'): if(!$studentProfile):?><section class="panel"><h3>Student not found</h3><p>The requested student record does not exist.</p><a class="btn btn-red" href="teacher.php">Back to dashboard</a></section><?php else:?>
<a class="back-link" href="teacher.php">← Back to dashboard</a><section class="student-hero panel"><div class="student-avatar"><?=e(strtoupper(substr($studentProfile['First_Name']?:$studentProfile['PlayerName'],0,1)))?></div><div><div class="eyebrow red">STUDENT RECORD</div><h2><?=e(trim(($studentProfile['First_Name']?:$studentProfile['PlayerName']).' '.$studentProfile['Middle_Initials'].' '.$studentProfile['Last_Name']))?></h2><p><?=e($studentProfile['Section'])?> · Student ID <?=e($studentProfile['ID'])?></p></div><div class="student-metrics"><div><small>Progress</small><strong><?=e($studentProfile['Progress'])?>%</strong></div><div><small>Mastery</small><strong><?=e($studentProfile['Mastery']??'—')?></strong></div></div></section><section class="panel"><div class="panel-heading"><div><h3>Pre-test & post-test scores</h3><p>Scores saved for this student in the database.</p></div></div><div class="table-scroll"><table><thead><tr><th>Chapter</th><th>Pre-test scores</th><th>Post-test scores</th></tr></thead><tbody><?php foreach($tests as $t):?><tr><td>Chapter <?=e($t['Chapter'])?></td><td><?=e($t['Pre_test_Scores'])?></td><td><?=e($t['Post_test_Scores'])?></td></tr><?php endforeach;?><?php if(!$tests):?><tr><td colspan="3" class="empty">No assessment scores have been recorded for this student yet. Add scores in the database table <code>records</code>.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
<?php elseif($page==='content'):?>
<div class="welcome-row"><div><h2>Manage learning content</h2><p>Edit a row, then select Save to write changes to <code>teacher_content</code>.</p></div><span class="date-chip"><?=count($content)?> activities</span></div><section class="panel"><div class="panel-heading"><div><h3>Activity question bank</h3><p>Each row is saved individually to the local MySQL database.</p></div></div><div class="table-scroll content-scroll"><table class="content-table"><thead><tr><th>#</th><th>Activity / question</th><th>Choice 1</th><th>Choice 2</th><th>Choice 3</th><th>Choice 4</th><th>Answer</th><th>Actions</th></tr></thead><tbody><?php foreach($content as $c):?><tr data-content-row="<?=e($c['Indicate'])?>"><td><?=e($c['Indicate'])?></td><?php foreach(['Exam'=>'activity','Choice1'=>'c1','Choice2'=>'c2','Choice3'=>'c3','Choice4'=>'c4','Answer'=>'answer'] as $field=>$key):?><td><textarea class="content-input" data-field="<?=e($key)?>" disabled rows="3"><?=e($c[$field])?></textarea></td><?php endforeach;?><td class="actions-cell"><button class="mini-btn edit-btn" type="button">Edit</button><form method="post" class="inline-form"><input type="hidden" name="action" value="save_content"><input type="hidden" name="id" value="<?=e($c['Indicate'])?>"><?php foreach(['activity','c1','c2','c3','c4','answer'] as $key):?><input type="hidden" name="<?=$key?>" value="<?=e($c[['activity'=>'Exam','c1'=>'Choice1','c2'=>'Choice2','c3'=>'Choice3','c4'=>'Choice4','answer'=>'Answer'][$key]])?>"><?php endforeach;?><button class="mini-btn save-btn" type="submit" disabled>Save</button></form><form method="post" class="inline-form reset-form" onsubmit="return confirm('Reset this row to the administrator default?')"><input type="hidden" name="action" value="reset_content"><input type="hidden" name="id" value="<?=e($c['Indicate'])?>"><button class="mini-btn reset-btn" type="submit" disabled>Reset</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($page==='profile'):?>
<div class="profile-layout"><section class="panel profile-card"><div class="profile-cover"></div><div class="profile-main"><?php if(!empty($teacher['Profile_Picture'])&&is_file(__DIR__.'/'.$teacher['Profile_Picture'])):?><img class="profile-photo" src="<?=e($teacher['Profile_Picture'])?>" alt="Teacher profile picture"><?php else:?><div class="profile-photo profile-placeholder"><?=e(strtoupper(substr($teacher['First_Name']?:'T',0,1)))?></div><?php endif;?><h2><?=e(full_name($teacher))?></h2><p><?=e($teacher['Subject']?:'Subject not set')?></p><form method="post" enctype="multipart/form-data" class="picture-form"><input type="hidden" name="action" value="picture"><label class="btn btn-outline file-button">Change picture<input type="file" name="picture" accept="image/png,image/jpeg,image/webp,image/gif" required></label><small>JPG, PNG, WEBP or GIF · Max 3 MB</small><button class="btn btn-red" type="submit">Upload picture</button></form></div><div class="profile-facts"><div><small>Teacher ID</small><strong><?=e($teacher['ID'])?></strong></div><div><small>Account created</small><strong><?=e($teacher['Date_Joined']?:'Not recorded')?></strong></div><div><small>Subject</small><strong><?=e($teacher['Subject']?:'Not set')?></strong></div></div></section><section class="panel profile-edit"><div class="panel-heading"><div><h3>Personal details</h3><p>Update your profile information.</p></div></div><form method="post" class="stack-form"><input type="hidden" name="action" value="profile"><div class="form-grid"><label>First name<input name="first" required value="<?=e($teacher['First_Name'])?>"></label><label>Middle name / initial<input name="middle" value="<?=e($teacher['Middle_Initials'])?>"></label><label>Last name<input name="last" required value="<?=e($teacher['Last_Name'])?>"></label><label>Subject<input name="subject" value="<?=e($teacher['Subject'])?>" placeholder="e.g. Computer Programming"></label></div><button class="btn btn-red" type="submit">Save profile</button></form><hr><div class="panel-heading"><div><h3>Change password</h3><p>New passwords are stored as secure hashes.</p></div></div><form method="post" class="stack-form"><input type="hidden" name="action" value="password"><label>Current password<input type="password" name="current_password" required autocomplete="current-password"></label><div class="form-grid"><label>New password<input type="password" name="new_password" minlength="8" required autocomplete="new-password"></label><label>Confirm new password<input type="password" name="confirm_password" minlength="8" required autocomplete="new-password"></label></div><button class="btn btn-red" type="submit">Update password</button></form><a class="btn btn-outline logout-profile" href="logout.php">↪ Log out</a></section></div>
